#include <zephyr/kernel.h>
#include <zephyr/sys/heap.h>
#include <zephyr/sys/util.h>
#include <string.h>

void k_heap_init(struct k_heap *h, void *mem, size_t bytes)
{
    sys_heap_init(&h->heap, mem, bytes);
}

void *k_heap_alloc(struct k_heap *h, size_t bytes, k_timeout_t timeout)
{
    void *ret;
    k_spinlock_key_t key = k_spin_lock(&h->lock);

    /* For k_heap, the timeout is generally not implemented as a blocking wait
     * within this generic wrapper. It's typically a non-blocking allocation.
     * If memory is not available, it returns NULL.
     */
    ret = sys_heap_alloc(&h->heap, bytes);

    k_spin_unlock(&h->lock, key);
    return ret;
}

void k_heap_free(struct k_heap *h, void *ptr)
{
    k_spinlock_key_t key = k_spin_lock(&h->lock);

    sys_heap_free(&h->heap, ptr);

    k_spin_unlock(&h->lock, key);
}

void *k_heap_calloc(struct k_heap *h, size_t num, size_t size, k_timeout_t timeout)
{
    size_t total_size;

    /* Check for multiplication overflow before allocating */
    if (z_calloc_size_mul_overflow(num, size, &total_size)) {
        return NULL; /* Multiplication overflowed */
    }

    void *ptr = k_heap_alloc(h, total_size, timeout);
    if (ptr != NULL) {
        (void)memset(ptr, 0, total_size);
    }
    return ptr;
}

void *k_heap_aligned_alloc(struct k_heap *h, size_t align, size_t bytes, k_timeout_t timeout)
{
    void *ret;
    k_spinlock_key_t key = k_spin_lock(&h->lock);

    /* Similar to k_heap_alloc, this is typically non-blocking for k_heap. */
    ret = sys_heap_aligned_alloc(&h->heap, align, bytes);

    k_spin_unlock(&h->lock, key);
    return ret;
}
